package com.anitec.backend;
import com.anitec.backend.identity.infrastructure.*;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.mock.env.MockEnvironment;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.*;
import java.time.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@Testcontainers
class EmailVerificationMigrationTests {
 @Container static PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:16-alpine");
 DriverManagerDataSource database(){String n="verification_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(new DriverManagerDataSource(postgres.getJdbcUrl(),postgres.getUsername(),postgres.getPassword())).execute("CREATE DATABASE "+n);return new DriverManagerDataSource("jdbc:postgresql://"+postgres.getHost()+":"+postgres.getMappedPort(5432)+"/"+n,postgres.getUsername(),postgres.getPassword());}
 Flyway flyway(DriverManagerDataSource d,String v){return Flyway.configure().dataSource(d).target(v).placeholders(Map.of("admin_email","retired@bootstrap.invalid","admin_password_hash","DISABLED-HISTORICAL-BOOTSTRAP","demo_seed","false")).load();}
 UUID account(JdbcTemplate j,String status,int resends,int attempts){return j.queryForObject("INSERT INTO identity_accounts(email,password_hash,name,last_name,role,status,verified_at,verification_code,verification_sent_at,verification_expires_at,verification_window_started_at,verification_resends,verification_attempts) VALUES (?,'preserved-hash','Test','Migration','GANADERO',?,CASE WHEN ?='ACTIVA' THEN now() ELSE NULL END,'000007',now()-interval '30 seconds',now()+interval '570 seconds',now()-interval '1 hour',?,?) RETURNING id",UUID.class,UUID.randomUUID()+"@example.invalid",status,status,resends,attempts);}
 UUID job(JdbcTemplate j,UUID a,String purpose,String state){UUID id=UUID.randomUUID(),emission=j.queryForObject("SELECT verification_emission_id FROM identity_accounts WHERE id=?",UUID.class,a);boolean live=List.of("PENDING","PROCESSING","RETRY_WAIT").contains(state);boolean processing=state.equals("PROCESSING");byte[] nonce=new byte[12];new java.security.SecureRandom().nextBytes(nonce);j.update("INSERT INTO identity_email_outbox(id,account_id,purpose,emission_id,state,ciphertext,nonce,attempts,next_attempt_at,expires_at,claim_id,claim_until,idempotency_key,provider_id,created_at,updated_at,completed_at) VALUES (?,?,?,?,?,?,?,?,now(),now()+interval '9 minutes',?,?,?, ?,now(),now(),?)",id,a,purpose,emission,state,live?new byte[32]:null,live?nonce:null,state.equals("PENDING")?0:1,processing?UUID.randomUUID():null,processing?java.sql.Timestamp.from(Instant.now().plusSeconds(60)):null,"anitec-email/"+id,state.equals("ACCEPTED")?UUID.randomUUID():null,live?null:java.sql.Timestamp.from(Instant.now()));return id;}
 Map<String,Object> row(JdbcTemplate j,String sql,Object...args){var m=j.queryForMap(sql,args);m.replaceAll((k,v)->v instanceof byte[] b?HexFormat.of().formatHex(b):v);return m;}
 @Test void freshInstallationAndRepeatInstallNoPlaintextWriters(){var d=database();assertThat(flyway(d,"latest").migrate().migrationsExecuted).isEqualTo(18);assertThat(flyway(d,"latest").migrate().migrationsExecuted).isZero();var j=new JdbcTemplate(d);assertThat(j.queryForObject("SELECT count(*) FROM identity_accounts",Integer.class)).isZero();assertThatThrownBy(()->account(j,"PENDIENTE",0,0)).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);}
 @Test void upgradePreservesAccountsPasswordsSessionsQuotasAndTimestamps(){var d=database();flyway(d,"17").migrate();var j=new JdbcTemplate(d);var ids=List.of(account(j,"PENDIENTE",2,3),account(j,"PENDIENTE",5,5),account(j,"ACTIVA",0,0),account(j,"SUSPENDIDA",4,2));var before=new HashMap<UUID,Map<String,Object>>();for(UUID id:ids)before.put(id,row(j,"SELECT * FROM identity_accounts WHERE id=?",id));UUID active=ids.get(2),session=UUID.randomUUID();UUID farm=j.queryForObject("INSERT INTO livestock_farms(farmer_id,name) VALUES (?,'Preserved farm') RETURNING id",UUID.class,active);var fb=row(j,"SELECT * FROM livestock_farms WHERE id=?",farm);j.update("INSERT INTO identity_sessions(id,account_id,created_at,expires_at) VALUES (?,?,now(),now()+interval '168 hours')",session,active);j.update("INSERT INTO identity_session_tokens(token_digest,session_id,created_at,expires_at) VALUES (?,?,now(),now()+interval '1 day')","a".repeat(64),session);var sb=row(j,"SELECT * FROM identity_sessions WHERE id=?",session);var tb=row(j,"SELECT * FROM identity_session_tokens WHERE session_id=?",session);assertThat(flyway(d,"latest").migrate().migrationsExecuted).isEqualTo(1);for(UUID id:ids){var after=row(j,"SELECT * FROM identity_accounts WHERE id=?",id);assertThat(after.remove("verification_verifier")).isNull();assertThat(after.get("verification_code")).isNull();before.get(id).put("verification_code",null);assertThat(after).isEqualTo(before.get(id));assertThat(j.queryForObject("SELECT identity_email_eligible(id,'EMAIL_VERIFICATION',verification_emission_id,now()) FROM identity_accounts WHERE id=?",Boolean.class,id)).isFalse();}assertThat(row(j,"SELECT * FROM identity_sessions WHERE id=?",session)).isEqualTo(sb);assertThat(row(j,"SELECT * FROM identity_session_tokens WHERE session_id=?",session)).isEqualTo(tb);assertThat(row(j,"SELECT * FROM livestock_farms WHERE id=?",farm)).isEqualTo(fb);}
 @Test void cancelsOnlyLiveLegacyVerificationAndErasesItsPayload(){var d=database();flyway(d,"17").migrate();var j=new JdbcTemplate(d);var legacy=new ArrayList<UUID>();for(String state:List.of("PENDING","PROCESSING","RETRY_WAIT"))legacy.add(job(j,account(j,"PENDIENTE",2,2),"EMAIL_VERIFICATION",state));UUID a=account(j,"ACTIVA",0,0),accepted=job(j,a,"EMAIL_VERIFICATION","ACCEPTED"),pw=job(j,a,"PASSWORD_RECOVERY","PENDING");j.update("INSERT INTO identity_password_recovery(account_id,purpose,window_started_at,emission_count,last_issued_at,emission_id,code_verifier,expires_at,failed_attempts) VALUES (?,'PASSWORD_RECOVERY',now(),2,now(),?,decode(repeat('ab',32),'hex'),now()+interval '10 minutes',1)",a,UUID.randomUUID());var ab=row(j,"SELECT * FROM identity_email_outbox WHERE id=?",accepted);var pb=row(j,"SELECT * FROM identity_email_outbox WHERE id=?",pw);var rb=row(j,"SELECT * FROM identity_password_recovery WHERE account_id=?",a);flyway(d,"latest").migrate();for(UUID id:legacy){var r=row(j,"SELECT * FROM identity_email_outbox WHERE id=?",id);assertThat(r.get("state")).isEqualTo("CANCELLED");assertThat(r.get("ciphertext")).isNull();assertThat(r.get("nonce")).isNull();assertThat(r.get("claim_id")).isNull();assertThat(r.get("completed_at")).isNotNull();assertThat(r.get("error_category")).isEqualTo("LEGACY_INVALIDATED");}assertThat(row(j,"SELECT * FROM identity_email_outbox WHERE id=?",accepted)).isEqualTo(ab);assertThat(row(j,"SELECT * FROM identity_email_outbox WHERE id=?",pw)).isEqualTo(pb);assertThat(row(j,"SELECT * FROM identity_password_recovery WHERE account_id=?",a)).isEqualTo(rb);}
 @Test void restartedWorkerCannotSendInvalidatedLegacyJob(){var d=database();flyway(d,"17").migrate();var j=new JdbcTemplate(d);job(j,account(j,"PENDIENTE",0,0),"EMAIL_VERIFICATION","PENDING");flyway(d,"latest").migrate();var e=new MockEnvironment().withProperty("email.delivery.mode","resend").withProperty("resend.api-key","synthetic-only").withProperty("resend.from","ANITEC <mail@notifications.vitalwatch.space>").withProperty("EMAIL_OUTBOX_ENCRYPTION_KEY",EmailCryptoSettingsTests.key());var sender=mock(ResendEmailSender.class);var worker=new EmailOutboxWorker(j,new EmailDeliverySettings(e),sender,Clock.systemUTC(),new DataSourceTransactionManager(d),e);assertThat(worker.runOne()).isFalse();verifyNoInteractions(sender);assertThat(j.queryForObject("SELECT ciphertext FROM identity_email_outbox",byte[].class)).isNull();}
 @Test void sqlRejectsPlaintextMalformedProofAndSameEmissionReplacement(){var d=database();flyway(d,"latest").migrate();var j=new JdbcTemplate(d);UUID a=j.queryForObject("INSERT INTO identity_accounts(email,password_hash,name,last_name,role,status,verification_sent_at,verification_expires_at) VALUES ('guard@example.invalid','synthetic-hash','Test','Guard','GANADERO','PENDIENTE',now(),now()+interval '10 minutes') RETURNING id",UUID.class);assertThatThrownBy(()->j.update("UPDATE identity_accounts SET verification_code='000007' WHERE id=?",a)).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);assertThatThrownBy(()->j.update("UPDATE identity_accounts SET verification_emission_id=?,verification_verifier=? WHERE id=?",UUID.randomUUID(),new byte[31],a)).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);assertThatThrownBy(()->j.update("UPDATE identity_accounts SET verification_verifier=? WHERE id=?",new byte[32],a)).isInstanceOf(org.springframework.dao.DataAccessException.class);j.update("UPDATE identity_accounts SET verification_emission_id=?,verification_verifier=? WHERE id=?",UUID.randomUUID(),new byte[32],a);assertThat(j.queryForObject("SELECT verification_code FROM identity_accounts WHERE id=?",String.class,a)).isNull();}
 @Test void incompatibleHistoricalEmissionIdsFailWithoutPartialInvalidation(){var d=database();flyway(d,"17").migrate();var j=new JdbcTemplate(d);UUID a=account(j,"PENDIENTE",2,3),b=account(j,"PENDIENTE",4,1);j.update("UPDATE identity_accounts SET verification_emission_id=(SELECT verification_emission_id FROM identity_accounts WHERE id=?) WHERE id=?",a,b);var beforeA=row(j,"SELECT * FROM identity_accounts WHERE id=?",a);var beforeB=row(j,"SELECT * FROM identity_accounts WHERE id=?",b);UUID work=job(j,a,"EMAIL_VERIFICATION","PENDING");var beforeJob=row(j,"SELECT * FROM identity_email_outbox WHERE id=?",work);assertThatThrownBy(()->flyway(d,"latest").migrate()).isInstanceOf(org.flywaydb.core.api.FlywayException.class);assertThat(row(j,"SELECT * FROM identity_accounts WHERE id=?",a)).isEqualTo(beforeA);assertThat(row(j,"SELECT * FROM identity_accounts WHERE id=?",b)).isEqualTo(beforeB);assertThat(row(j,"SELECT * FROM identity_email_outbox WHERE id=?",work)).isEqualTo(beforeJob);assertThat(j.queryForObject("SELECT count(*) FROM flyway_schema_history WHERE version='18' AND success",Integer.class)).isZero();}

}
